#include <SPI.h>
#include <Adafruit_GFX.h>
#include <Adafruit_ILI9341.h>

#define TFT_CS    22
#define TFT_DC     2
#define TFT_RST    4

#define TFT_SCLK  18
#define TFT_MISO  19
#define TFT_MOSI  23

Adafruit_ILI9341 tft(TFT_CS, TFT_DC, TFT_RST);

void showTest() {
    tft.fillScreen(ILI9341_RED);
      delay(1000);

        tft.fillScreen(ILI9341_GREEN);
          delay(1000);

            tft.fillScreen(ILI9341_BLUE);
              delay(1000);

                tft.fillScreen(ILI9341_WHITE);
                  delay(1000);

                    tft.fillScreen(ILI9341_BLACK);

                      tft.drawRect(5, 5, 230, 310, ILI9341_RED);
                        tft.drawRect(10, 10, 220, 300, ILI9341_GREEN);

                          tft.setTextColor(ILI9341_WHITE);
                            tft.setTextSize(3);
                              tft.setCursor(25, 40);
                                tft.println("ESP32");

                                  tft.setCursor(25, 80);
                                    tft.println("TFT TEST");

                                      tft.setTextSize(2);
                                        tft.setCursor(25, 130);
                                          tft.println("ILI9341");

                                            tft.fillCircle(60, 210, 30, ILI9341_RED);
                                              tft.fillCircle(150, 210, 30, ILI9341_GREEN);
                                                tft.fillCircle(105, 270, 30, ILI9341_BLUE);
}

void setup() {
    Serial.begin(115200);

      SPI.begin(TFT_SCLK, TFT_MISO, TFT_MOSI, TFT_CS);

        tft.begin();
          tft.setRotation(0);

            showTest();
}

void loop() {
}
}
